INSERT /* SQL_ID: CollectionWorkMapperMapper.insertCollectionWork */
INTO dtmeta.tb_meta_collectionwork (
      colec_wrk_id
    , colec_wrk_sttus_mtcd
    , colec_log_id
    , root_medata_set_id
    , cret_medata_set_id_list
    , colec_wrk_msg
    , colec_wrk_reg_dt
    , colec_wrk_amd_dt
) VALUES(
      #{colecWrkId}
    , #{colecWrkSttusMtcd}
    , #{colecLogId}
    , #{rootMedataSetId}
    , #{cretMedataSetIdList}::jsonb
    , #{colecWrkMsg}
    , current_timestamp
    , current_timestamp
)

