UPDATE /* SQL_ID: CollectionWorkMapperMapper.updateCollectionWork */
 dtmeta.tb_meta_collectionwork
SET  colec_wrk_sttus_mtcd		= #{colecWrkSttusMtcd}
    , root_medata_set_id		= #{rootMedataSetId}
    , cret_medata_set_id_list	= #{cretMedataSetIdList}::jsonb
    , colec_wrk_msg				= #{colecWrkMsg}
    , colec_wrk_amd_dt			= current_timestamp
WHERE colec_wrk_id				= #{colecWrkId}
